/* ===== Phase 7: architecture walkthroughs ===== */
/* GRID lays nodes out on a regular grid. rows: [[cell...]], cell = null or [id, label, sub, kind]
   edges: [[from, to, label, dashed]]; groups: [[label, row0, col0, row1, col1, cls]] */
function GRID(rows, edges, caption, groups) {
  const CW = 172, CH = 58, GX = 62, GY = 58, PY = 36, MINCOLS = 4;
  let cols = 0; rows.forEach(row => { cols = Math.max(cols, row.length); });
  const span = n => n * CW + (n - 1) * GX, W = 52 + span(Math.max(cols, MINCOLS)), PX = (W - span(cols)) / 2;
  const nodes = [];
  rows.forEach((row, r) => row.forEach((c, i) => { if (c) nodes.push({ id: c[0], label: c[1], sub: c[2] || undefined, kind: c[3] || 'external', x: PX + i * (CW + GX), y: PY + r * (CH + GY), w: CW, h: CH }); }));
  return {
    w: W, h: PY + rows.length * CH + (rows.length - 1) * GY + 22,
    groups: (groups || []).map(g => ({ label: g[0], cls: g[5], x: PX + g[2] * (CW + GX) - 14, y: PY + g[1] * (CH + GY) - 26, w: (g[4] - g[2] + 1) * CW + (g[4] - g[2]) * GX + 28, h: (g[3] - g[1] + 1) * CH + (g[3] - g[1]) * GY + 40 })),
    nodes, edges: edges.map(e => ({ from: e[0], to: e[1], label: e[2], dashed: e[3] })), caption
  };
}
const WT = o => WALKTHROUGHS.push(o);

